<script>
import generateCodeJson  from '../utils/rest/generate';
export default {
  name: 'RestfulApi',
  props: {
    // 父组件传入完整文档对象：{ title, en, info, api: { request/response/error/payload/responseBody/... } }
    content: { type: Object, default: () => ({}) },
    // 可选：默认代码高亮语言（和 hljs 的 language-xxx 对齐）
    codeLang: { type: String, default: 'json' },
    // 可选：当 payload/responseBody 是对象时，是否自动 JSON.stringify
    stringify: { type: Boolean, default: true }
  },

  data() {
    return {
      // 当前选中的语言
      activeLang: 'python',
      // 代码示例 Tabs 的激活语言名（需和 class 'language-xxx' 对齐）
      activeCodeTab: this.codeLang,
      tableData: [
        { env: 'PROD', address: 'https://open-api.bingx.com' },
        { env: 'VST',  address: 'https://open-api-vst.bingx.com' }
      ],
      msgMap: {
        success: {
          '繁体中文': '複製成功',
          'English': 'Copy Successfully'
        },
        error: {
          '繁体中文': '複製失敗',
          'English': 'Copy Failed'
        }
      },
      demoHtml: ''
    }
  },

  computed: {
    // ---- 下面全部从 props.content 安全派生（无 ?.） ----
    restApiRequest() {
      var api = (this.content && this.content.api) ? this.content.api : null
      var list = api && api.request && Array.isArray(api.request.list) ? api.request.list : []
      return list
    },
    restApiResponse() {
      var api = (this.content && this.content.api) ? this.content.api : null
      var list = api && api.response && Array.isArray(api.response.list) ? api.response.list : []
      return list
    },
    errorList() {
      var api = (this.content && this.content.api) ? this.content.api : null
      var list = api && api.error && Array.isArray(api.error.list) ? api.error.list : []
      return list
    },
    payloadRaw() {
      var api = (this.content && this.content.api) ? this.content.api : null
      return api && api.payload ? api.payload : ''
    },
    responseBodyRaw() {
      var api = (this.content && this.content.api) ? this.content.api : null
      return api && api.responseBody ? api.responseBody : ''
    },
    // 给 v-html 用：保证是字符串
    payloadHtml() {
      var v = this.payloadRaw
      if (typeof v === 'string') return v
      if (this.stringify) {
        try { return JSON.stringify(v, null, 2) } catch(e) { return String(v) }
      }
      return String(v)
    },
    responseBodyHtml() {
      var v = this.responseBodyRaw
      if (typeof v === 'string') return v
      if (this.stringify) {
        try { return JSON.stringify(v, null, 2) } catch(e) { return String(v) }
      }
      return String(v)
    },
    // 按照语言显示不同的按钮文本
    copyCodeBtnText() {
      return {
        '繁体中文': '複製代碼',
        'English': 'Copy Code',
      }[this.$store.state.lang || 'English']; // 默认英语
    },
  },

  methods: {
    scrollToElement(tab) {
      // 标签名与 ref 对应
      var label = tab && tab.label ? tab.label : ''
      var el = this.$refs[label]
      if (el && el.scrollIntoView) {
        el.scrollIntoView({ behavior: 'smooth' })
      }
    },
    tableRowClassName(args) {
      // 可按你真实数据结构调整：这里兼容 row.type / row.level
      var row = args && args.row ? args.row : null
      if (!row) return ''
      if (row.type === 'breaking' || row.level === 'breaking') return 'warning-row'
      if (row.type === 'fix' || row.level === 'success') return 'success-row'
      return ''
    },
    // 根据当前语言和 API 数据生成代码
    generateCode() {
      // 确保 this.api 已经传入，并从中获取 uri, method, payload
      const api = {
        uri: (this.content && this.content.api && this.content.api.uri) || '',  // 确保安全访问
        method: (this.content && this.content.api && this.content.api.method) || 'GET',  // 若没有 method，则默认为 'GET'
        payload: (this.content && this.content.api && this.content.api.payload) || {},  // 若没有 payload，则默认为空对象
        protocol: 'https',  // 默认设置协议为 https
      };


      // 获取 host 地址
      const host = (this.tableData.find(item => item.env === 'PROD') && this.tableData.find(item => item.env === 'PROD').address) || '';
      // console.log('api',api)
      // console.log('host',host)
      // 使用 generateCodeJson 生成代码，并将其赋值给 payloadHtml
      this.demoHtml = generateCodeJson(api, this.activeLang, host, 'No code available');
      // console.log('demoHtml',this.demoHtml)
      // 使用 nextTick 确保 DOM 更新完成后再设置样式
      this.$nextTick(() => {
        this.adjustHeights(); // 调用样式调整方法
      });
    },

    // 复制成功回调
    onCopy() {
      this.$message.success(this.msgMap['success'][this.$store.state.lang]);  // 显示成功消息
    },

    // 复制失败回调
    onError() {
      this.$message.error(this.msgMap['error'][this.$store.state.lang]);  // 显示错误消息
    },
    adjustHeights() {
      // 获取所有带有 .code-html.demo-code 类的元素
      const codeBlocks = document.querySelectorAll('.code-html.demo-code');

      // 遍历每个 code block 设置高度
      codeBlocks.forEach((block) => {
        // 先重置高度
        block.style.height = 'auto';

        // 如果内容为空，设置一个默认高度
        if (!block.innerHTML.trim()) {
          block.style.height = '200px';  // 设置默认高度
        } else {
          block.style.height = `${block.scrollHeight}px`;  // 设置为内容的实际高度
        }
      });
    }
  },
  mounted() {
    // 页面加载时，默认生成代码
    this.generateCode();
    // 页面加载时调整高度
    this.adjustHeights();

  },
  watch: {
    codeLang(newVal) {
      // 父组件切换默认语言时，同步 tabs 选中
      this.activeCodeTab = newVal || 'json'
    }
  }
}
</script>



